function minOperations(nums) {
  const n = nums.length;
  let operations = 0;

  for (let i = 0; i + 2 < n; i++) {
    if (nums[i] === 0) {
      nums[i] = 1;
      nums[i + 1] ^= 1;
      nums[i + 2] ^= 1;
      operations++;
    }
  }
  if (nums[n - 2] === 0 || nums[n - 1] === 0) {
    return -1;
  }
  return operations;
}

