function minOperations(nums) {
  // Flipping a window twice cancels out and the order of flips does not matter,
  // so try every set of windows and keep the smallest one that leaves only ones.
  const windows = nums.length - 2;
  let best = -1;
  for (let mask = 0; mask < (1 << windows); mask++) {
    const bits = nums.slice();
    let used = 0;
    for (let w = 0; w < windows; w++) {
      if (!(mask & (1 << w))) continue;
      used++;
      for (let j = w; j < w + 3; j++) bits[j] = 1 - bits[j];
    }
    if (bits.every(b => b === 1) && (best === -1 || used < best)) best = used;
  }
  return best;
}

