function generate(rand, size) {
  const n = size === 'large' ? 2000 : 3 + Math.floor(rand() * 10);
  let nums;
  if (rand() < 0.6) {
    // Start from all ones and apply random windows, so the input can be solved.
    nums = new Array(n).fill(1);
    const moves = Math.floor(rand() * (size === 'large' ? 600 : 6));
    for (let m = 0; m < moves; m++) {
      const start = Math.floor(rand() * (n - 2));
      for (let j = start; j < start + 3; j++) nums[j] ^= 1;
    }
  } else {
    const density = rand();
    nums = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  }
  return [nums];
}
